#!/usr/bin/env node
// Guard runner. See docs/framework/guard-rules.md (generated by --docs).
// Exit codes: 0 pass, 1 violations beyond baseline, 2 usage error or guard malfunction.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { CLAUDE_FILE, claudeProblem, writeClaude } from './lib/claude-md.mjs';
import { CODEOWNERS_FILE, PROTECTED_FILE, codeownersInSync, loadProtected, writeCodeowners } from './lib/codeowners.mjs';
import { BASELINE_FILE, compare, countsOf, loadBaseline, lowered, show, totalOf, writeBaseline } from './lib/baseline.mjs';
import { DOCS_FILE, docsInSync, writeDocs } from './lib/docs.mjs';
import { createContext, git } from './lib/files.mjs';
import { runProtect } from './lib/protect.mjs';
import { MAX_LINE, SELF_DIRS, selfCheck, unprotectedManifests } from './lib/selfcheck.mjs';
import { DEFAULT_RULES, RULES } from './rules/index.mjs';
import g09 from './rules/g09-change-id.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const RESULT_DIR = '.guard';
const MAX_LOCATIONS = 8;
const FLAGS = ['--update-baseline', '--init-baseline', '--docs', '--codeowners', '--strict'];
const VALUE_FLAGS = { '--commits': '<base>..<head>', '--protect': '<base-ref>' };
const USAGE = [...FLAGS, ...Object.entries(VALUE_FLAGS).map(pair => pair.join(' '))];
// Only these rules may have entries in the baseline. An entry for a rule without a baseline is a guard error.
const BASELINE_KINDS = Object.fromEntries(DEFAULT_RULES.filter(rule => rule.baseline !== 'none').map(rule => [rule.id, rule.baseline]));

function parseArgs(argv) {
  const options = {};
  for (let i = 0; i < argv.length; i += 1) {
    const cut = argv[i].startsWith('--') ? argv[i].indexOf('=') : -1;
    const [name, inline] = cut > 0 ? [argv[i].slice(0, cut), argv[i].slice(cut + 1)] : [argv[i]];
    if (Object.hasOwn(VALUE_FLAGS, name)) {
      options[name.slice(2)] = inline ?? argv[i + 1] ?? '';
      if (inline === undefined) i += 1;
    } else if (FLAGS.includes(argv[i])) options[name.slice(2)] = true;
    else fail(2, `알 수 없는 옵션: ${argv[i]}\n사용법: node scripts/guard/run.mjs [${USAGE.join(' | ')}]`);
  }
  const modes = ['update-baseline', 'init-baseline', 'docs', 'codeowners', 'commits', 'protect'].filter(key => options[key] !== undefined);
  if (modes.length > 1 || (options.strict && (options.commits !== undefined || options.protect !== undefined))) {
    fail(2, `함께 쓸 수 없는 옵션: ${[...modes, ...(options.strict ? ['strict'] : [])].map(key => `--${key}`).join(', ')}`);
  }
  return options;
}

function fail(code, message) {
  console.error(`[guard] ${message}`);
  process.exit(code);
}

function meta() {
  const commit = git(root, ['rev-parse', 'HEAD']).trim();
  const dirty = git(root, ['status', '--porcelain']).trim().length > 0;
  return { evidenceKind: 'SYNTHETIC', evidenceNote: '정적 검사 결과. 실제 DB·서버를 쓰지 않았다.', commit, workingTreeDirty: dirty, timestamp: new Date().toISOString() };
}

function writeResult(name, body) {
  fs.mkdirSync(path.join(root, RESULT_DIR), { recursive: true });
  fs.writeFileSync(path.join(root, RESULT_DIR, name), `${JSON.stringify({ ...meta(), ...body }, null, 2)}\n`);
}

const where = (file, line) => (line > 0 ? `${file}:${line}` : file);

function printRule(row) {
  const total = row.baseline === 'none' ? `현재 ${show(row.currentTotal)}` : `기준선 ${show(row.baselineTotal)} / 현재 ${show(row.currentTotal)}`;
  console.log(`${row.id} ${row.name.padEnd(22)} ${row.status.padEnd(5)} ${total}${row.newViolations.length ? `  새 위반 파일 ${row.newViolations.length}` : ''}`);
  if (row.error) console.log(`    오류: ${row.error}`);
  for (const item of row.newViolations) {
    if (row.baseline !== 'none') console.log(`    ${item.file}: 기준선 ${show(item.baseline)} -> 현재 ${show(item.current)}`);
    for (const spot of item.locations.slice(0, MAX_LOCATIONS)) console.log(`      ${where(item.file, spot.line)}  ${spot.message}`);
    const more = item.locations.length - MAX_LOCATIONS;
    if (more > 0) console.log(`      ... 외 ${more}곳 (이 파일의 전체 위치는 ${RESULT_DIR}/guard-result.json)`);
  }
}

function runRules(ctx) {
  return DEFAULT_RULES.map(rule => {
    try {
      const findings = rule.check(ctx);
      for (const finding of findings) if (typeof finding.file !== 'string') throw new Error('규칙이 파일 없는 결과를 냈습니다.');
      return { rule, findings };
    } catch (error) {
      return { rule, findings: [], error: error.message };
    }
  });
}

function runCommits(range) {
  let outcome;
  try { outcome = g09.checkRange(root, range); } catch (error) { fail(2, `G09 를 돌릴 수 없습니다: ${error.message.split('\n')[0]}`); }
  const { commits, findings, exempt, start } = outcome;
  if (commits.length + exempt === 0) fail(2, `G09: 범위 ${range} 안에 검사할 커밋이 없습니다. 빈 범위는 통과가 아니라 오류입니다(범위를 잘못 준 것일 수 있습니다).`);
  const status = findings.length ? 'FAIL' : 'PASS';
  const skipped = `규칙 도입 전이라 뺀 커밋 ${exempt}개(시작점 ${start.slice(0, 12)} 과 그 조상)`;
  console.log(`${g09.id} ${g09.name.padEnd(22)} ${status.padEnd(5)} 범위 ${range}  검사한 커밋 ${commits.length}개 / ID 없는 커밋 ${findings.length}개 / ${skipped}`);
  for (const finding of findings) console.log(`    ${finding.file}  ${finding.message}`);
  const rule = { id: g09.id, name: g09.name, status, checkedCommits: commits.length, exemptCommits: exempt, lastExemptCommit: start, newViolations: findings };
  writeResult('guard-commits-result.json', { status, range, rules: [rule] });
  process.exit(findings.length ? 1 : 0);
}

function initBaseline(runs) {
  if (fs.existsSync(path.join(root, BASELINE_FILE))) {
    fail(2, `거부: ${BASELINE_FILE} 이 이미 있습니다. --init-baseline 은 처음 한 번만 쓸 수 있습니다. 줄어든 숫자는 --update-baseline 으로 반영하세요.`);
  }
  const broken = runs.filter(run => run.error);
  if (broken.length) fail(2, `기준선을 만들 수 없습니다. 규칙 오류: ${broken.map(run => `${run.rule.id} ${run.error}`).join(' / ')}`);
  const rules = {};
  for (const { rule, findings } of runs) if (rule.baseline !== 'none') rules[rule.id] = countsOf(rule, findings);
  writeBaseline(root, rules);
  console.log(`[guard] ${BASELINE_FILE} 을 만들었습니다.`);
  return rules;
}

function main() {
  const options = parseArgs(process.argv.slice(2));
  if (options.docs) {
    writeDocs(root, RULES);
    writeClaude(root, RULES);
    console.log(`[guard] ${DOCS_FILE} 과 ${CLAUDE_FILE} 의 만들어 넣는 구간을 다시 만들었습니다.`);
    return 0;
  }
  if (options.codeowners) { writeCodeowners(root); console.log(`[guard] ${CODEOWNERS_FILE} 을 다시 만들었습니다.`); return 0; }
  if (options.commits !== undefined) runCommits(options.commits);
  if (options.protect !== undefined) return runProtect(root, options.protect, meta, RESULT_DIR);

  const ctx = createContext(root);
  const runs = runRules(ctx);
  const tooLong = selfCheck(ctx);
  let frozen = options['init-baseline'] ? initBaseline(runs) : loadBaseline(root, BASELINE_KINDS);
  if (!frozen) fail(2, `${BASELINE_FILE} 이 없습니다. 처음이라면 --init-baseline 으로 만드세요.`);

  const rows = runs.map(({ rule, findings, error }) => {
    const result = compare(rule, findings, rule.baseline === 'none' ? {} : frozen[rule.id]);
    const status = error ? 'ERROR' : result.newViolations.length ? 'FAIL' : 'PASS';
    return { id: rule.id, name: rule.name, baseline: rule.baseline, status, error, ...result };
  });

  if (options['update-baseline']) {
    const next = { ...frozen };
    let changed = 0;
    for (const row of rows) {
      if (row.baseline === 'none' || row.status === 'ERROR') continue;
      changed += row.lowerable.length;
      next[row.id] = lowered(frozen[row.id] ?? {}, row.counts);
    }
    if (changed) writeBaseline(root, next);
    console.log(`[guard] 기준선 갱신: ${changed}개 항목을 내렸습니다. (올리거나 추가하는 일은 하지 않습니다)`);
    frozen = next;
    for (const row of rows) if (row.baseline !== 'none' && row.status !== 'ERROR') { row.baselineTotal = totalOf(next[row.id]); row.lowerable = []; }
  }

  rows.forEach(printRule);
  const docsOk = docsInSync(root, RULES);
  if (!docsOk) console.log(`DOCS ${DOCS_FILE} 이 규칙과 다릅니다. node scripts/guard/run.mjs --docs 를 실행하세요.`);
  const ownersOk = codeownersInSync(root);
  if (!ownersOk) console.log(`OWNERS ${CODEOWNERS_FILE} 이 보호 경로 목록과 다릅니다. node scripts/guard/run.mjs --codeowners 를 실행하세요.`);
  const claude = claudeProblem(root, RULES);
  if (claude) console.log(`CLAUDE ${claude}`);
  const loose = unprotectedManifests(ctx, loadProtected(root));
  if (loose.length) console.log(`MANIFEST 보호 경로 목록(${PROTECTED_FILE})에 없는 package.json: ${loose.join(', ')}. 목록에 넣으세요.`);
  // Self-check: an unreadable guard is a guard malfunction (ERROR), not an ordinary violation.
  if (tooLong.length) console.log(`SELF ${SELF_DIRS.join(', ')} 에 ${MAX_LINE}자를 넘는 줄이 ${tooLong.length}개 있습니다 (가드 오류).`);
  for (const spot of tooLong.slice(0, MAX_LOCATIONS)) console.log(`    ${where(spot.file, spot.line)}  ${spot.length}자`);
  const lowerable = rows.reduce((n, row) => n + row.lowerable.length, 0);
  if (lowerable) console.log(`[guard] 기준선을 내릴 수 있는 항목 ${lowerable}개. pnpm guard --update-baseline 으로 반영하세요.`);

  const errored = rows.some(row => row.status === 'ERROR') || tooLong.length > 0;
  const synced = docsOk && ownersOk && !claude && loose.length === 0;
  const failed = rows.some(row => row.status === 'FAIL') || !synced || (options.strict && lowerable > 0);
  const status = errored ? 'ERROR' : failed ? 'FAIL' : 'PASS';
  writeResult('guard-result.json', {
    status, docsInSync: docsOk, codeownersInSync: ownersOk, claudeInSync: !claude, unprotectedManifests: loose, baselineLowerable: lowerable,
    selfCheck: { status: tooLong.length ? 'ERROR' : 'PASS', maxLineLength: MAX_LINE, tooLong },
    rules: rows.map(({ counts, lowerable: canLower, baseline, ...row }) => ({ ...row, baselineKind: baseline, lowerable: canLower })),
  });
  console.log(`[guard] ${status}  (결과: ${RESULT_DIR}/guard-result.json)`);
  return errored ? 2 : failed ? 1 : 0;
}

try { process.exit(main()); } catch (error) { fail(2, `가드가 멈췄습니다: ${error.stack ?? error}`); }
